/**
 * Non-regression on the REAL Lyon fixture: the current code must reproduce expected/lyon-reference-routes.json
 * (generated by scripts/report-data.mts) within tolerance. Skipped when the fixture is absent.
 */
import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { analyzeRoute } from '../src/core/analysis';
import { assignElevations, correctAnomalies, fillMissingElevations, vertexElevationsById } from '../src/core/elevation';
import { LYON_CENTRE } from '../src/core/geo';
import { buildGraph, parseOverpass, stairsStats, type OverpassJson } from '../src/core/osm';
import { routeThrough } from '../src/core/router';
import type { RoutingPreferences } from '../src/core/cost';

const FIX = 'fixtures/lyon-centre.overpass.json';
const IGN = 'fixtures/lyon-centre.ign-alti.json';
const EXP = 'expected/lyon-reference-routes.json';
const available = existsSync(FIX) && existsSync(IGN) && existsSync(EXP);

describe.skipIf(!available)('Lyon centre real fixture', () => {
  const osm = available ? (JSON.parse(readFileSync(FIX, 'utf8')) as OverpassJson) : { elements: [] };
  const ways = parseOverpass(osm);
  const graph = buildGraph(ways, { bbox: LYON_CENTRE });
  if (available) {
    const ign = JSON.parse(readFileSync(IGN, 'utf8')) as { nodes: Record<string, number> };
    assignElevations(graph, vertexElevationsById(graph, ign.nodes));
    fillMissingElevations(graph);
    correctAnomalies(graph);
  }
  const expected = available ? (JSON.parse(readFileSync(EXP, 'utf8')) as { tolerance: { relative: number; absoluteM: number }; cases: { id: string; input: { waypoints: { lng: number; lat: number }[]; prefs: RoutingPreferences }; expected: { length: number; gain: number; loss: number; steps: number; stairsEdges: number; climbs: { name: string | null; gain: number }[] } }[] }) : { tolerance: { relative: 0, absoluteM: 0 }, cases: [] };

  it('has a realistic graph with hundreds of stairs', () => {
    const s = stairsStats(ways);
    expect(s.ways).toBeGreaterThan(150);
    expect(graph.nodes.length).toBeGreaterThan(10000);
    expect(graph.edges.every((e) => e.eles && e.eles.every(Number.isFinite))).toBe(true);
  });

  for (const c of expected.cases) {
    it(`reproduces ${c.id}`, () => {
      const route = routeThrough(graph, c.input.waypoints, c.input.prefs);
      expect(route).not.toBeNull();
      const a = analyzeRoute(graph, route!);
      const tol = (v: number): number => Math.max(expected.tolerance.absoluteM, v * expected.tolerance.relative);
      expect(Math.abs(a.length - c.expected.length)).toBeLessThanOrEqual(tol(c.expected.length));
      expect(Math.abs(a.gainLoss.gain - c.expected.gain)).toBeLessThanOrEqual(tol(c.expected.gain));
      expect(Math.abs(a.gainLoss.loss - c.expected.loss)).toBeLessThanOrEqual(tol(c.expected.loss));
      expect(a.breakdown.totalSteps).toBe(c.expected.steps);
      expect(a.breakdown.stairsEdges).toBe(c.expected.stairsEdges);
      expect(a.climbs.length).toBe(c.expected.climbs.length);
    });
  }

  it('Tête d’Or (flat) has no climb and Gourguillon has one big climb', () => {
    const flat = expected.cases.find((c) => c.id === 'tete-dor-plat');
    if (flat) expect(flat.expected.climbs.length).toBe(0);
    const g = expected.cases.find((c) => c.id === 'gourguillon');
    if (g) expect(g.expected.gain).toBeGreaterThan(60);
  });
});
